mapper.select:
select
    ,
    e.id as employee_profile_id,
    e.employee_no, e.department_id, e.position_name,
    e.employment_status, e.hired_on, e.left_on
from member m
inner join employee_profile e on e.member_id = m.id

    m.member_type = 'EMPLOYEE'

    and e.id = #{member.employeeProfileId}
    and e.employee_no = #{member.employeeNo}
    and e.department_id = #{member.departmentId}
    and e.position_name like concat('%', #{member.positionName}, '%')
    and e.employment_status = #{member.employmentStatus}
    and e.hired_on = #{member.hiredOn}
    and e.left_on = #{member.leftOn}

order by m.id desc

select count(*) from member
where (name = #{name} or email = #{email} or phone = #{phone})
and id != #{excludeId}

mapper.update:
update reader_settings
personalization_enabled = #{reader.personalizationEnabled}, recommendation_notifications = #{reader.recommendationNotificationsEnabled}, member_id = member_id,
where member_id = #{memberId}

update employee_profile
employee_no = #{employee.employeeNo}, department_id = #{employee.departmentId}, position_name = #{employee.positionName}, employment_status = #{employee.employmentStatus}, hired_on = #{employee.hiredOn}, left_on = #{employee.leftOn}, member_id = member_id,
where member_id = #{memberId}

mapper.select:
select m.id, m.name, m.member_type, d.name as department_name
from member m
join `role` r on r.id = m.role_id and r.status = 'ACTIVE'
left join employee_profile ep on ep.member_id = m.id
left join department d on d.id = ep.department_id
where m.id <> #{memberId}
  and m.account_status = 'ACTIVE'
  and m.member_type in ('READER', 'EMPLOYEE')
and m.id = #{q.id}
and m.name like concat('%', #{q.name}, '%')
and m.member_type = #{q.memberType}
and ep.department_id = #{q.departmentId}
and ep.department_id = #{scopeDepartmentId}
order by m.id desc
